/* HEXA BATTLEGROUNDS setup — PART 68 OF 82. Run parts in order. Safe to re-run. */ insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-signal-20', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["purple","yellow","white","blue","green","yellow","green"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 6\nGreen = 3\nBlue = 2\nYellow = 5\nPurple = 5\nWhite = 5"},"intel":{"title":"How to read it","body":"Read the flashes in REVERSE order (last flash first)."}}'::jsonb, '[{"label":"Code","accept":["3532555"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'purple,yellow,white,blue,green,yellow,green → green,yellow,green,blue,white,yellow,purple → 3532555', null, 25, 'published'), ('mission-signal-21', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["purple","green","white","white","purple","green"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 6\nGreen = 4\nBlue = 1\nYellow = 5\nPurple = 7\nWhite = 5"},"intel":{"title":"How to read it","body":"Use only every SECOND flash (the 2nd, 4th, 6th…)."}}'::jsonb, '[{"label":"Code","accept":["454"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'purple,green,white,white,purple,green → green,white,green → 454', null, 25, 'published'), ('mission-signal-22', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["white","red","blue","red","yellow","green"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 4\nGreen = 3\nBlue = 6\nYellow = 3\nPurple = 6\nWhite = 5"},"intel":{"title":"How to read it","body":"Ignore every WHITE flash, then read the rest in order."}}'::jsonb, '[{"label":"Code","accept":["46433"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'white,red,blue,red,yellow,green → red,blue,red,yellow,green → 46433', null, 25, 'published'), ('mission-signal-23', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["red","white","blue","red","purple","yellow","purple"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 4\nGreen = 7\nBlue = 4\nYellow = 4\nPurple = 2\nWhite = 6"},"intel":{"title":"How to read it","body":"Read them in order, but skip any colour you have already read once."}}'::jsonb, '[{"label":"Code","accept":["46424"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'red,white,blue,red,purple,yellow,purple → red,white,blue,purple,yellow → 46424', null, 25, 'published'), ('mission-signal-24', 'signal', 'mission', 'Signal Lights', 'game', 1, array['transmission','terrace','observation','gate','public','any']::text[], 'A lamp on the roof is flashing a code. Scout watches it, Decoder knows what each colour means, Intel knows how to read it.', '{"scout":{"title":"Rooftop lamp","body":"Press Play and watch the lamp. Call out every colour as it flashes. You can replay it three times.","game":{"type":"signal","seq":["white","white","yellow","purple","blue","white","blue"],"replays":3}},"decoder":{"title":"Colour key","body":"Red = 5\nGreen = 4\nBlue = 7\nYellow = 7\nPurple = 1\nWhite = 4"},"intel":{"title":"How to read it","body":"Use only the first FOUR flashes, in order."}}'::jsonb, '[{"label":"Code","accept":["4471"]}]'::jsonb, false, 3, 200, 'Scout: write the colours down as they flash. Intel: apply the reading rule. Decoder: turn colours into digits last.', 'white,white,yellow,purple,blue,white,blue → white,white,yellow,purple → 4471', null, 25, 'published'), ('mission-pattern-0', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[0,1,3,7]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock is the right way up."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n8  6  9\n4  2  7\n1  5  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["8645"]}]'::jsonb, false, 3, 200, 'First turn Intel''s picture back the right way using Scout''s note, then read Decoder''s number for each dot in order.', 'true path 0-1-3-7 → 8645', null, 25, 'published') on conflict (id) do update set family = excluded.family, kind = excluded.kind, title = excluded.title, category = excluded.category, difficulty = excluded.difficulty, tags = excluded.tags, objective = excluded.objective, clues = excluded.clues, parts = excluded.parts, relay = excluded.relay, attempts = excluded.attempts, time_limit = excluded.time_limit, hint = excluded.hint, explanation = excluded.explanation, points = excluded.points, coins = excluded.coins, status = excluded.status, version = case when mission_templates.clues is distinct from excluded.clues or mission_templates.parts is distinct from excluded.parts then mission_templates.version + 1 else mission_templates.version end, updated_at = now(); insert into mission_templates(id, family, kind, title, category, difficulty, tags, objective, clues, parts, relay, attempts, time_limit, hint, explanation, points, coins, status) values ('mission-pattern-1', 'pattern', 'mission', 'Pattern Lock', 'logic', 1, array['office','helpdesk','learning','social','any']::text[], 'An abandoned phone is locked with a swipe pattern. Intel has a photo of the pattern, Scout knows how the photo was taken, Decoder knows the numbers behind the dots.', '{"intel":{"title":"Photo of the swipe","body":"The line starts at the green dot. Describe each dot in order.","game":{"type":"pattern","path":[6,3,0,4,1]}},"scout":{"title":"How the photo was taken","body":"Intel''s photo of the lock was taken UPSIDE DOWN (turned 180°)."},"decoder":{"title":"This phone''s keypad","body":"The 9 dots carry these numbers (top row first):\n7  8  9\n4  5  6\n1  2  3"}}'::jsonb, '[{"label":"PIN from the pattern","accept":["96352"]}]'::jsonb, false, 3, 200, 'First turn Int